contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSumVal, address logAddr) public payable {
        bool initReverted;
        bool initReverted2;
        uint minSumBefore;

        // Fresh contract: intitalized is false, so SetMinSum must succeed.
        c.SetMinSum(minSumVal); if (__ESBMC_reverted()) return;

        // Read the public getter after the state-changing call.
        minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        // Initialized must succeed on a fresh contract.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Now intitalized is true; both setters must revert regardless of arguments.
        c.SetMinSum(minSumVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }
        c.SetLogFile(logAddr); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initReverted2 = true; } else { initReverted2 = false; }

        assert(
            minSumBefore == minSumVal &&
            initReverted &&
            initReverted2 &&
            c.MinSum() == minSumVal
        );
    }

    receive() external payable {}
}

