pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 minSumVal, address logAddr) internal {
        bool initReverted;
        bool initReverted2;
        uint minSumBefore;
        try c.SetMinSum(minSumVal) {} catch { return; }
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(minSumVal) { initReverted = false; } catch { initReverted = true; }
        try c.SetLogFile(logAddr) { initReverted2 = false; } catch { initReverted2 = true; }
        assertTrue(minSumBefore == minSumVal &&
            initReverted &&
            initReverted2 &&
            c.MinSum() == minSumVal);
    }

    function testFuzz_run(uint256 minSumVal, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(minSumVal, logAddr);
    }

    receive() external payable {}
}
